/* ---------- Fig: the control graph, lit by real recorded paths ---------- */
FIGS.graph = (el) => {
  const W = 920, H = 560, E = P().svgEl, T = P().txt;
  const svg = E('svg', { viewBox: `0 0 ${W} ${H}`, width: W, height: H }, el);
  const sx = (i) => 66 + i * 131, sy = 270;
  const spine = ['understand', 'route', 'collect', 'check', 'preview', 'commit', 'confirm'];
  const pos = {}; spine.forEach((n, i) => (pos[n] = [sx(i), sy, 112, false]));
  Object.assign(pos, { onboard: [sx(1.5), 105, 160, true], ask_certificate: [sx(3.05), 105, 176, true], fix_cost_centre: [sx(2), 440, 160, true], approval: [sx(4.5), 440, 120, true], answer: [sx(0), 105, 100, true], hold: [sx(3.5), 520, 92, true], ask_kavita: [sx(5.4), 105, 132, true], wait_approval: [sx(6), 440, 140, true] });
  const gates = { onboard: 'supplier not found', fix_cost_centre: 'centre closed', ask_certificate: 'food contact, no cert', approval: 'over the limit' };
  spine.forEach((n, i) => { if (i) E('line', { x1: sx(i - 1) + 56, y1: sy, x2: sx(i) - 56, y2: sy, style: 'stroke:var(--ink);stroke-width:1.5' }, svg); });
  const els = {};
  Object.entries(pos).forEach(([n, [x, y, w, det]]) => {
    if (det && gates[n]) { E('line', { x1: x, y1: y < sy ? y + 24 : y - 24, x2: x, y2: y < sy ? sy - 26 : sy + 26, style: 'stroke:var(--ink-3);stroke-width:1.5;stroke-dasharray:6 5' }, svg); T(svg, x + 8, (y + sy) / 2 + 5, gates[n], 'font:13px var(--mono);fill:var(--ink-2)'); }
    const r = E('rect', { x: x - w / 2, y: y - 24, width: w, height: 48, rx: det ? 24 : 4 }, svg);
    const t = T(svg, x, y + 6, NODE_TITLE[n], `font:${det ? 16 : 17}px var(--serif)`, 'middle');
    const b = T(svg, x + w / 2 - 4, y - 28, '', 'font:600 14px var(--mono);fill:var(--after)', 'end');
    els[n] = { r, t, b, det, pause: n === 'ask_kavita' || n === 'wait_approval' };
  });
  const note = T(svg, 8, H - 6, '', 'font:italic 18px var(--display);fill:var(--ink-2)');
  const labels = Object.keys(L4.paths || {});
  const c = ctl(el, labels.map((l, i) => `<button data-i="${i}">${esc(l.split(' · ')[0])}</button>`).join('') + '<span class="pl" style="flex-basis:100%;font-size:14px;line-height:1.5"></span>');
  let cur = null, shown = 0;
  const paint = () => {
    const p = cur == null ? null : L4.paths[labels[cur]];
    const cnt = {}; (p ? p.path : []).forEach((n) => (cnt[n] = (cnt[n] || 0) + 1));
    Object.entries(els).forEach(([n, e]) => {
      const on = !!cnt[n], vis = !e.det || shown >= 1;
      const col = n === 'hold' && on ? 'var(--before)' : e.pause && on ? 'var(--gold)' : on ? 'var(--after)' : e.det ? 'var(--ink-3)' : 'var(--ink)';
      e.r.setAttribute('style', `fill:${on ? (n === 'hold' ? 'var(--before-soft)' : e.pause ? '#F1E9D2' : 'var(--after-soft)') : e.det ? 'var(--paper)' : 'var(--card)'};stroke:${col};stroke-width:${on ? 2.5 : 1.5};stroke-dasharray:${e.det && !on ? '6 5' : 'none'};opacity:${vis ? 1 : 0}`);
      e.t.style.opacity = vis ? 1 : 0; e.t.style.fill = on ? col : 'var(--ink-2)';
      e.b.textContent = cnt[n] > 1 ? `×${cnt[n]}` : '';
    });
    note.textContent = p ? `${labels[cur]} · ${p.path.length} nodes · ${p.passed ? 'passed' : 'failed'} · from ${p.src}` : 'Dashed detours are skipped unless their gate opens. Pick a recorded run.';
    c.querySelector('.pl').textContent = p ? p.path.map((n) => NODE_TITLE[n] || n).join(' › ') : '';
    c.querySelectorAll('button').forEach((b) => b.classList.toggle('on', +b.dataset.i === cur));
  };
  c.addEventListener('click', (e) => { const b = e.target.closest('button'); if (b) { cur = +b.dataset.i; paint(); } });
  return { step(k) { shown = k; if (k >= 2 && cur == null) cur = 0; if (k < 2) cur = null; paint(); } };
};

